/**
 * designBlocks.ts
 *
 * The scaffold blocks Design Space can place on a sheet: frames, ties,
 * clamps, jacks, brackets and the rest, drawn as line work.
 *
 * They are the company's own drafting blocks, converted from the Bluebeam
 * tool set "SSI - Scaffold Blocks - Frame" - the same drawings an estimator
 * already stamps on a plan, so a sheet marked up here reads like one marked
 * up there. The plan-view bays and elevation bays of that set are left out:
 * Korban sets bays out itself, from a run.
 *
 * Each block is drawn in points at the tool set's own scale, a quarter inch
 * to the foot, so 18 units are one foot. Placed on a sheet it is scaled to
 * that sheet, which is what makes a 5' frame five feet wide on the drawing.
 *
 * This file is generated from the tool set. To change a block, change it
 * there and convert again; do not edit the path data by hand.
 */

export type DesignBlock = {
  id: string;
  name: string;
  group: string;
  /** The drawing's box, in points. */
  w: number;
  h: number;
  /** The line weight most of the drawing uses, in points. */
  sw: number;
  /** The drawing itself: SVG shapes that take the colour they are given. */
  svg: string;
};

/** Points to the foot in every block. */
export const BLOCK_UNITS_PER_FOOT = 18;

/** The palette's groups, in the order they are shown. */
export const BLOCK_GROUPS: string[] = ["Ties + Clamps", "Heads + Bases", "Frames", "Brackets + Posts", "Other"];

